def countBoundedShift(n, d):
    M = 1000000007
    W = 2 * d + 1
    init = 0
    for j in range(W):
        if 1 - d + j <= 0:
            init |= 1 << j
    dp = {init: 1}
    for i in range(1, n + 1):
        nd = {}
        for mask, w in dp.items():
            for j in range(W):
                if (mask >> j) & 1:
                    continue
                if i - d + j > n:
                    break
                nm = mask | (1 << j)
                if not nm & 1:
                    continue
                nm >>= 1
                nd[nm] = (nd.get(nm, 0) + w) % M
        dp = nd
    return sum(dp.values()) % M
